/**
 * Plausible operational-lot area. Above is a business park. The lower limit
 * was 3,000 m² while the roof check was missing (a smaller area was almost
 * always a showroom); small dealers are the sites the engine is weakest on,
 * so they belong in the set.
 */
const MIN_AREA_SQM = 1_500;
const MAX_AREA_SQM = 60_000;
/** Sites per region; a region may override it (`perRegion`). */
const PER_REGION = 6;
/**
 * At most this share of a reference may lie under OSM building footprints.
 * A lot with a large showroom is about half roof; a reference that is all
 * roof is the showroom, whatever its tags.
 */
const MAX_ROOF_SHARE = 0.6;
/** Candidates checked for roofs per region, richest outlines first. */
const ROOF_CHECK_CANDIDATES = 24;
/**
 * Two references closer than this share imagery and parcels; only the
 * richer one is kept.
 */
const MIN_SPACING_M = 400;
/**
 * A 4-corner box is a mapper's placeholder, not a digitised outline. Using one
 * as a reference would mostly measure how well the engine reproduces someone
 * else's rectangle.
 */
const MIN_VERTICES = 8;

const METERS_PER_DEGREE = 111_320;

function ringAreaSqm(ring) {
  if (ring.length < 4) return 0;
  const cosLat = Math.cos((ring[0][1] * Math.PI) / 180);
  let area = 0;
  for (let i = 0; i < ring.length - 1; i += 1) {
    const x1 = (ring[i][0] - ring[0][0]) * METERS_PER_DEGREE * cosLat;
    const y1 = (ring[i][1] - ring[0][1]) * METERS_PER_DEGREE;
    const x2 = (ring[i + 1][0] - ring[0][0]) * METERS_PER_DEGREE * cosLat;
    const y2 = (ring[i + 1][1] - ring[0][1]) * METERS_PER_DEGREE;
    area += x1 * y2 - x2 * y1;
  }
  return Math.abs(area / 2);
}

function centroidOf(ring) {
  let lon = 0;
  let lat = 0;
  for (let i = 0; i < ring.length - 1; i += 1) {
    lon += ring[i][0];
    lat += ring[i][1];
  }
  const n = ring.length - 1;
  return [lon / n, lat / n];
}

function closeRing(ring) {
  const first = ring[0];
  const last = ring[ring.length - 1];
  if (first[0] !== last[0] || first[1] !== last[1]) ring.push([...first]);
  return ring;
}

/** Rejects slivers and near-degenerate shapes that make poor references. */
function isPlausibleLot(ring) {
  if (ring.length - 1 < MIN_VERTICES) return false;
  const area = ringAreaSqm(ring);
  if (area < MIN_AREA_SQM || area > MAX_AREA_SQM) return false;
  let minLon = Infinity, maxLon = -Infinity, minLat = Infinity, maxLat = -Infinity;
  for (const [lon, lat] of ring) {
    minLon = Math.min(minLon, lon); maxLon = Math.max(maxLon, lon);
    minLat = Math.min(minLat, lat); maxLat = Math.max(maxLat, lat);
  }
  const cosLat = Math.cos((minLat * Math.PI) / 180);
  const width = (maxLon - minLon) * METERS_PER_DEGREE * cosLat;
  const height = (maxLat - minLat) * METERS_PER_DEGREE;
  if (width < 20 || height < 20) return false;
  const aspect = Math.max(width, height) / Math.min(width, height);
  if (aspect > 6) return false;
  // A lot should fill a decent share of its bounding box.
  return area / (width * height) > 0.45;
}

function pointInRing(ring, lon, lat) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i, i += 1) {
    const [xi, yi] = ring[i];
    const [xj, yj] = ring[j];
    if (yi > lat !== yj > lat && lon < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) {
      inside = !inside;
    }
  }
  return inside;
}

function ringBox(ring) {
  let west = Infinity, south = Infinity, east = -Infinity, north = -Infinity;
  for (const [lon, lat] of ring) {
    west = Math.min(west, lon); east = Math.max(east, lon);
    south = Math.min(south, lat); north = Math.max(north, lat);
  }
  return [south, west, north, east];
}

/** Share of a ring's area under the given building rings, on a 2 m lattice. */
export function roofShare(ring, buildings) {
  const [south, west, north, east] = ringBox(ring);
  const dLat = 2 / METERS_PER_DEGREE;
  const dLon = dLat / Math.cos((south * Math.PI) / 180);
  const near = buildings.filter((b) => {
    const [bs, bw, bn, be] = ringBox(b);
    return bw <= east && be >= west && bs <= north && bn >= south;
  });
  let inside = 0;
  let roof = 0;
  for (let lat = south + dLat / 2; lat < north; lat += dLat) {
    for (let lon = west + dLon / 2; lon < east; lon += dLon) {
      if (!pointInRing(ring, lon, lat)) continue;
      inside += 1;
      if (near.some((b) => pointInRing(b, lon, lat))) roof += 1;
    }
  }
  return inside === 0 ? 1 : roof / inside;
}

function distanceM(a, b) {
  const cosLat = Math.cos((a.lat * Math.PI) / 180);
  return Math.hypot(
    (a.lon - b.lon) * METERS_PER_DEGREE * cosLat,
    (a.lat - b.lat) * METERS_PER_DEGREE,
  );
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** Tries each mirror, then backs off and retries. 504/429 are routine here. */
async function overpass(query, attempts = 3) {
  let lastError = new Error("no attempt made");
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    for (const url of OVERPASS_MIRRORS) {
      try {
        const res = await fetch(url, {
          method: "POST",
          headers: { "Content-Type": "text/plain", "User-Agent": USER_AGENT },
          body: query,
          signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
        });
        if (res.ok) return res.json();
        lastError = new Error(`${res.status} ${res.statusText}`);
      } catch (error) {
        lastError = error;
      }
      await sleep(1_000);
    }
    await sleep(3_000 * 2 ** attempt);
  }
  throw lastError;
}

/** OSM building footprints (ways and multipolygon outers) inside the boxes. */
async function fetchBuildings(boxes) {
  if (boxes.length === 0) return [];
  const parts = boxes
    .map(([s, w, n, e]) => `wr["building"](${s},${w},${n},${e});`)
    .join("");
  const data = await overpass(`[out:json][timeout:90];(${parts});out geom;`);
  const rings = [];
  for (const element of data.elements ?? []) {
    if (element.type === "way" && Array.isArray(element.geometry)) {
      if (element.geometry.length >= 4) {
        rings.push(closeRing(element.geometry.map((p) => [p.lon, p.lat])));
      }
    } else if (element.type === "relation") {
      for (const member of element.members ?? []) {
        if (member.role !== "outer" || !Array.isArray(member.geometry)) continue;
        if (member.geometry.length < 4) continue;
        rings.push(closeRing(member.geometry.map((p) => [p.lon, p.lat])));
      }
    }
  }
  return rings;
}

async function fetchRegion(region) {
  const candidates = [];
  for (const area of region.areas) {
    const [south, west, north, east] = area.bbox;
    // No `building` tag: a dealer tag on a building is the showroom, not the lot.
    const query = `
[out:json][timeout:90][bbox:${south},${west},${north},${east}];
way["shop"="car"]["name"][!"building"][!"building:part"];
out geom 400;`;
    const data = await overpass(query);
    for (const element of data.elements ?? []) {
      if (element.type !== "way" || !Array.isArray(element.geometry)) continue;
      if (element.geometry.length < 4) continue;
      const ring = closeRing(element.geometry.map((p) => [p.lon, p.lat]));
      if (!isPlausibleLot(ring)) continue;
      const [lon, lat] = centroidOf(ring);
      candidates.push({
        id: `${region.key}-${element.id}`,
        osmType: "way",
        osmId: element.id,
        lon: Number(lon.toFixed(6)),
        lat: Number(lat.toFixed(6)),
        areaSqm: Math.round(ringAreaSqm(ring)),
        vertices: ring.length - 1,
        country: region.country,
        state: region.state,
        city: area.city,
        cadastreAvailable: region.cadastre,
        reference: {
          type: "Polygon",
          coordinates: [
            ring.map(([x, y]) => [Number(x.toFixed(7)), Number(y.toFixed(7))]),
          ],
        },
      });
    }
    await sleep(1_500);
  }
  // Prefer the richest outlines available in the region.
  candidates.sort((a, b) => b.vertices - a.vertices || a.id.localeCompare(b.id));
  const shortlist = candidates.slice(0, ROOF_CHECK_CANDIDATES);
  // An untagged roof is still a roof: measure how much of each outline lies
  // under mapped buildings.
  const buildings = await fetchBuildings(
    shortlist.map((c) => ringBox(c.reference.coordinates[0])),
  );
  const limit = region.perRegion ?? PER_REGION;
  const kept = [];
  let roofs = 0;
  for (const candidate of shortlist) {
    if (kept.length >= limit) break;
    const share = roofShare(candidate.reference.coordinates[0], buildings);
    if (share > MAX_ROOF_SHARE) {
      roofs += 1;
      continue;
    }
    if (kept.some((other) => distanceM(other, candidate) < MIN_SPACING_M)) continue;
    kept.push({ ...candidate, roofShare: Number(share.toFixed(2)) });
  }
  return { kept, candidates: candidates.length, roofs };
}

async function main() {
  const outArg = process.argv.indexOf("--out");
  const outPath = resolve(
    outArg === -1
      ? "resources/benchmarks/boundary-public-fixtures.json"
      : process.argv[outArg + 1],
  );

  const samples = [];
  for (const region of REGIONS) {
    process.stdout.write(`${region.key} ... `);
    try {
      const found = await fetchRegion(region);
      samples.push(...found.kept);
      console.log(
        `${found.kept.length} sample(s) of ${found.candidates} candidate(s), ${found.roofs} rejected as roofs`,
      );
    } catch (error) {
      console.log(`failed (${error.message})`);
    }
    // Be a good citizen on the shared public instance.
    await sleep(2_000);
  }

  // Geographic hold-out, not a random split: whole regions are held out so a
  // site cannot leak into tuning via a neighbour a few hundred metres away.
  const holdoutRegions = new Set(["de-sh", "de-st", "de-th", "de-bw", "at-9"]);
  for (const sample of samples) {
    const region = REGIONS.find((r) => r.state === sample.state);
    sample.holdout = holdoutRegions.has(region?.key ?? "");
  }

  const payload = {
    dataset: "boundary-public-v2",
    license: "ODbL-1.0",
    attribution: "© OpenStreetMap contributors",
    generatedAt: new Date().toISOString().slice(0, 10),
    note:
      "Reference polygons are publicly mapped car-dealership areas in OSM. " +
      "They are a proxy for the operational lot, not a survey: OSM mappers " +
      "vary in how much of the forecourt and staff parking they include. " +
      "Ways tagged as buildings, and outlines that lie mostly under mapped " +
      "buildings (roofShare), are excluded.",
    holdoutRegions: [...holdoutRegions],
    samples: samples.sort((a, b) => a.id.localeCompare(b.id)),
  };

  writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(
    `\nwrote ${samples.length} samples (${samples.filter((s) => s.holdout).length} held out) to ${outPath}`,
  );
}

// Run only as a script, so the roof test can be imported by a unit test.
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
